NAMES={'current_reference':'线上旧五类参考','ordinary_historical':'历史普通 v9','balanced_historical':'历史均衡 v9b','guarded_v11':'历史保守 v11','ordinary_control':'匹配普通 · 原人工数据','balanced_control':'匹配均衡 · 原人工数据','ordinary_augmented':'上一轮 v12 · 普通','balanced_augmented':'上一轮 v12 · 均衡', 'ordinary_boundary':'上一轮 v13 · 普通修正', 'balanced_positive_only':'上一轮 v13 · 无细类负例', 'balanced_boundary':'上一轮 v13 · 均衡修正', 'loss_v14':'v14 · 仅改训练方法', 'context_v14':'v14 · 跨面结构', 'gated_v14':'v14 · 跨面与存在判断', 'context_calibrated_v14':'v14 · 跨面与训练内校准'}
